-- 2026-11-19 (her rule that day): the 8 hours a week minimum is gone. Rates are based on 8 or more hours a week, under 8 hours a week is
-- $5 more an hour, and Early Support Visits are the regular rate plus $5 an hour (no $152 / $140 visit prices), plus the one-time $99.
-- Five answers change, each only when its text still differs. Nothing is added, no title or topic changes, and no status changes:
--   K102 (rates), K103 (minimum hours; it stays held if it is held), K157 (Early Support Visits): the website chat. Same text as
--   supabase/knowledge/cara-2026-10-27.mjs.
--   OR27 (Exhibit J on the tablet), OR17 (Regular care): office rules for Ask Cara in the Hub. Internal answers never reach the website chat.
update public.kb_items set answer = 'Our published rates are Wellness Care $30 an hour, Personal Care $32 an hour, and Advanced Care $34 an hour. Overnight and 24-Hour Care use the same hourly rates, based on the level of care needed. These rates are based on 8 or more hours of care a week. With fewer than 8 hours a week, the rate is $5 more an hour. An in-home assessment gives you an exact number for your schedule and needs.', version = version + 1, verified_on = '2026-11-19', verified_by = 'Samantha 11-19: rates based on 8 or more hours a week, under 8 is $5 more', updated_at = now()
  where id = 'K102' and audience = 'public' and answer is distinct from 'Our published rates are Wellness Care $30 an hour, Personal Care $32 an hour, and Advanced Care $34 an hour. Overnight and 24-Hour Care use the same hourly rates, based on the level of care needed. These rates are based on 8 or more hours of care a week. With fewer than 8 hours a week, the rate is $5 more an hour. An in-home assessment gives you an exact number for your schedule and needs.';
update public.kb_items set answer = 'Visits are 4 hours or more. Our rates are based on 8 or more hours of care a week. With fewer than 8 hours a week, the rate is $5 more an hour. A visit under 4 hours, when the office can approve one, is also $5 more an hour.', version = version + 1, verified_on = '2026-11-19', verified_by = 'Samantha 11-19: rates based on 8 or more hours a week, under 8 is $5 more', updated_at = now()
  where id = 'K103' and audience = 'public' and answer is distinct from 'Visits are 4 hours or more. Our rates are based on 8 or more hours of care a week. With fewer than 8 hours a week, the rate is $5 more an hour. A visit under 4 hours, when the office can approve one, is also $5 more an hour.';
update public.kb_items set answer = 'Early Support Visits are for older adults in Springfield who are doing well at home and would like a helping hand around the house and good company now and then. A caregiver comes for a 4-hour visit once a month or every other week. Visits are billed at our regular rate plus $5 an hour, which is from $35 an hour, so a visit starts at $140. Before visits begin there is a one-time $99 in-home assessment and setup, billed with the first visit. See mo-care.com/early-support-visits or call (417) 234-8494.', version = version + 1, verified_on = '2026-11-19', verified_by = 'Samantha 11-19: rates based on 8 or more hours a week, under 8 is $5 more', updated_at = now()
  where id = 'K157' and audience = 'public' and answer is distinct from 'Early Support Visits are for older adults in Springfield who are doing well at home and would like a helping hand around the house and good company now and then. A caregiver comes for a 4-hour visit once a month or every other week. Visits are billed at our regular rate plus $5 an hour, which is from $35 an hour, so a visit starts at $140. Before visits begin there is a one-time $99 in-home assessment and setup, billed with the first visit. See mo-care.com/early-support-visits or call (417) 234-8494.';
update public.kb_items set answer = 'Early Support Visits (office steps). A separate program, not a fourth care level. Springfield only. One 4-hour visit once a month or every other week, billed at the regular rate plus $5 an hour ($35 an hour for Wellness Care, so $140 a visit). No weekly option. One-time $99 assessment and setup, billed with the first visit; nothing is paid at the assessment. It is Exhibit J of the Client Care Agreement: on the tablet''s set-up screen tick the enrolling box, pick the schedule, type the regular visit day, and enter the hourly rate as the regular rate plus $5. Regular care rates are based on 8 or more hours a week; under 8 hours a week is $5 more an hour. Never promise the same caregiver or an extra visit. Steps are on Payors & Programs, Early Support Visits tab.', verified_on = '2026-11-19', verified_by = 'Samantha 11-19: rates based on 8 or more hours a week, under 8 is $5 more', updated_at = now()
  where id = 'OR27' and audience = 'internal' and answer is distinct from 'Early Support Visits (office steps). A separate program, not a fourth care level. Springfield only. One 4-hour visit once a month or every other week, billed at the regular rate plus $5 an hour ($35 an hour for Wellness Care, so $140 a visit). No weekly option. One-time $99 assessment and setup, billed with the first visit; nothing is paid at the assessment. It is Exhibit J of the Client Care Agreement: on the tablet''s set-up screen tick the enrolling box, pick the schedule, type the regular visit day, and enter the hourly rate as the regular rate plus $5. Regular care rates are based on 8 or more hours a week; under 8 hours a week is $5 more an hour. Never promise the same caregiver or an extra visit. Steps are on Payors & Programs, Early Support Visits tab.';
update public.kb_items set answer = '4-hour visits. Rates are based on 8 or more hours a week. Under 8 hours a week is $5 more an hour. A visit under 4 hours, when the office approves one, is $5 more an hour. Both together is $10 more an hour. Visits less often than weekly (Early Support Visits) are the rate plus $5, with a one-time $99 assessment and setup.', verified_on = '2026-11-19', verified_by = 'Samantha 11-19: rates based on 8 or more hours a week, under 8 is $5 more', updated_at = now()
  where id = 'OR17' and audience = 'internal' and answer is distinct from '4-hour visits. Rates are based on 8 or more hours a week. Under 8 hours a week is $5 more an hour. A visit under 4 hours, when the office approves one, is $5 more an hour. Both together is $10 more an hour. Visits less often than weekly (Early Support Visits) are the rate plus $5, with a one-time $99 assessment and setup.';
